# Explicit Constructor Injection + Composition Root (Python)
from typing import Protocol

class PaymentGateway(Protocol):
    def charge(self, order_id: str, cents: int) -> str: ...

class CheckoutService:
    def __init__(self, gateway: PaymentGateway, clock) -> None:
        self._gateway = gateway  # Immutable collaborator, testable without container
        self._clock = clock

    def checkout(self, order_id: str, cents: int) -> dict:
        tx_id = self._gateway.charge(order_id, cents)
        return {'order_id': order_id, 'tx_id': tx_id, 'ts': self._clock.now()}
